using UnityEditor;

namespace Protobot.Editor
{
    /// <summary>Cursor icons (generated by Tools/Textures/make_cursors.py) import as uncompressed hardware cursors.</summary>
    public class UiTextureImport : AssetPostprocessor
    {
        public const string CursorFolder = "Assets/Protobot/Art/UI/Cursors/";

        void OnPreprocessTexture()
        {
            if (!assetPath.StartsWith(CursorFolder))
                return;

            var importer = (TextureImporter)assetImporter;
            importer.textureType = TextureImporterType.Cursor;
            importer.alphaIsTransparency = true;
            importer.mipmapEnabled = false;
            importer.textureCompression = TextureImporterCompression.Uncompressed;
            importer.npotScale = TextureImporterNPOTScale.None;
        }
    }
}
